import { defineConfig } from 'orval';

// Generates the typed API client + React Query hooks from the contract.
// The contract (docs/openapi.yaml) is the single source of truth: never edit src/api/generated by hand.
export default defineConfig({
  splitapp: {
    input: { target: '../docs/openapi.yaml' },
    output: {
      mode: 'single',
      target: 'src/api/generated/splitapp.ts',
      schemas: 'src/api/generated/model',
      client: 'react-query',
      httpClient: 'fetch',
      clean: true,
      override: {
        mutator: { path: 'src/api/http.ts', name: 'customFetch' },
        query: { version: 5 },
      },
    },
  },
});
